<?php
declare(strict_types=1);
require_once __DIR__ . '/../../services/CejuscRegistrosService.php';
$id = trim((string) ($_GET['id'] ?? ''));
$registro = $id !== '' ? (new CejuscRegistrosService(Conection::getInstance()->getConnection()))->find($id) : null;
if (!$registro) { http_response_code(404); echo 'Registro CEJUSC não encontrado.'; exit; }
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Edição CEJUSC</title><?php include __DIR__ . '/_internal_head_styles.php'; ?><?php include __DIR__ . '/_toast_script.php'; ?></head>
<body class="page-internal"><div class="spacing-top-page"></div><div class="header-page"><div class="location"><span class="all">Interno - Cartório - Cejusc -</span><span class="specific">Edição</span></div><h1 class="title-page">Editar cadastro CEJUSC</h1><p class="description-page">Atualize os dados do encaminhamento.</p></div>
<div class="container-full card-page"><form id="cejusc-form"><input type="hidden" name="id" value="<?php echo htmlspecialchars($id, ENT_QUOTES); ?>"><div class="display-flex row row-full padding-x-md padding-y-md border-bottom gap-y-md"><div class="col filter"><label for="processo">Número do processo</label><input class="width-500 height-md" id="processo" name="numero_processo" required value="<?php echo htmlspecialchars((string) $registro['numero_processo'], ENT_QUOTES); ?>"></div><div class="col filter"><label for="parte">Nome da parte</label><input class="width-600 height-md" id="parte" name="nome_parte" required maxlength="180" value="<?php echo htmlspecialchars((string) $registro['nome_parte'], ENT_QUOTES); ?>"></div><div class="col filter"><label for="data-envio">Data de envio ao CEJUSC</label><input class="width-250 height-md" type="date" id="data-envio" name="data_envio_cejusc" required value="<?php echo htmlspecialchars((string) $registro['data_envio_cejusc'], ENT_QUOTES); ?>"></div></div><div class="card-buttons"><button type="button" class="btn btn-secondary" onclick="location.href='/frame.php?page=cejusc'">Voltar</button><button type="button" class="btn btn-danger" id="delete">Excluir</button><button class="btn btn-primary" type="submit">Salvar</button></div></form></div>
<script>const form=document.getElementById('cejusc-form');async function send(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Operação não concluída.');return d;}form.addEventListener('submit',async e=>{e.preventDefault();try{await send('/api/cartorio-cejusc/update.php',Object.fromEntries(new FormData(form)));location.href='/frame.php?page=cejusc';}catch(x){if(window.App&&App.Page)App.Page.notify('error','Erro',x.message);else alert(x.message);}});document.getElementById('delete').addEventListener('click',async()=>{if(!confirm('Excluir este registro CEJUSC?'))return;try{const d=await send('/api/cartorio-cejusc/delete.php',{id:form.id.value});if(d.deleted)location.href='/frame.php?page=cejusc';}catch(x){if(window.App&&App.Page)App.Page.notify('error','Erro',x.message);else alert(x.message);}});</script></body></html>
